mapper.select:
SELECT EXTRACT(YEAR FROM r.completed_at) as year, COUNT(*) as reservationCount FROM RESERVATION r JOIN ASSET a ON r.asset_id = a.asset_id WHERE a.is_deleted = 'N' AND r.completed_at IS NOT NULL AND EXTRACT(YEAR FROM r.completed_at) BETWEEN 2016 AND 2025
AND a.category = #{category}
AND a.name = #{model}
AND r.address_city = #{address}
GROUP BY EXTRACT(YEAR FROM r.completed_at) ORDER BY year

SELECT EXTRACT(YEAR FROM m.resolved_at) as year, COUNT(*) as inspectionCount FROM MAINTENANCE m JOIN ASSET a ON m.asset_id = a.asset_id WHERE a.is_deleted = 'N' AND m.resolved_at IS NOT NULL AND EXTRACT(YEAR FROM m.resolved_at) BETWEEN 2016 AND 2025
AND a.category = #{category}
AND a.name = #{model}
GROUP BY EXTRACT(YEAR FROM m.resolved_at) ORDER BY year
